export type Card = {
  monster: string;
  rank?: number;
};

const SCORE_WITHOUT_SPHINX = 0;
// Every army with a sphinx seen so far scores 2. Whether that 2 is a flat
// amount, a per-sphinx rate, or a per-type count is not yet distinguished by
// any passing test — the name stays neutral until one does.
const SCORE_WITH_SPHINX = 2;

const containsSphinx = (army: Card[]): boolean =>
  army.some((card) => card.monster === "sphinx");

export const scoreArmy = (army: Card[]): number => {
  if (containsSphinx(army)) return SCORE_WITH_SPHINX;
  return SCORE_WITHOUT_SPHINX;
};

