import { describe, it, expect } from "vitest";
import { scoreArmy } from "./sphinx-score.js";

describe("Sphinx scoring", () => {
  it("scores an army with no Sphinx as 0 — Chimera, Orthrus, Zombie → 0", () => {
    expect(
      scoreArmy([
        { monster: "chimera" },
        { monster: "orthrus" },
        { monster: "zombie" },
      ]),
    ).toBe(0);
  });
  it("scores a Sphinx with three types as 1 point each — Sphinx, Chimera, Orthrus → 2", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "chimera" },
        { monster: "orthrus" },
      ]),
    ).toBe(2);
  });
  it("scores a Sphinx with fewer than three types as 1 point each — Sphinx, Cyclops → 2", () => {
    expect(scoreArmy([{ monster: "sphinx" }, { monster: "cyclops" }])).toBe(2);
  });
  it("counts duplicate cards of the same monster once — Sphinx, Chimera, Chimera, Chimera, Orthrus, Orthrus → 2", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "chimera" },
        { monster: "chimera" },
        { monster: "chimera" },
        { monster: "orthrus" },
        { monster: "orthrus" },
      ]),
    ).toBe(2);
  });
  it("scores 2 per type beyond three — Sphinx, Chimera, Orthrus, Zombie, Hydra → 3", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "chimera" },
        { monster: "orthrus" },
        { monster: "zombie" },
        { monster: "hydra" },
      ]),
    ).toBe(3);
  });
  it("scores 2 per type beyond three with two extra types — Sphinx, Chimera, Orthrus, Zombie, Hydra, Cyclops → 5", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "chimera" },
        { monster: "orthrus" },
        { monster: "zombie" },
        { monster: "hydra" },
        { monster: "cyclops" },
      ]),
    ).toBe(5);
  });
  it.todo("scores each Sphinx separately, counting Sphinx as one type — Sphinx, Sphinx, Chimera, Orthrus → 4");
  it.todo("scores each Sphinx separately beyond three types — Sphinx, Sphinx, Chimera, Orthrus, Zombie → 6");
  it.todo("treats Undead Warrior ranks as a single type — Sphinx, Undead Warrior(1), Undead Warrior(3), Chimera → 2");
  it.todo("treats all three Undead Warrior ranks as one type in a larger army — Sphinx, Undead Warrior(1,2,3), Cyclops, Orthrus, Chimera → 3");
});

export type Card = {
  monster: string;
  rank?: number;
};

const SCORE_WITHOUT_SPHINX = 0;
const SPHINX_POINT = 1;
const POINT_FOR_THREE_OTHER_TYPES_OR_FEWER = 1;
const OTHER_TYPE_THRESHOLD = 3;
const POINTS_PER_OTHER_TYPE_BEYOND_THRESHOLD = 2;
/** The Sphinx scores the *company* it keeps, so its own type is not counted. */
const SPHINX_OWN_TYPE = 1;

const containsSphinx = (army: Card[]): boolean =>
  army.some((card) => card.monster === "sphinx");

const countTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

const countOtherTypes = (army: Card[]): number =>
  countTypes(army) - SPHINX_OWN_TYPE;

const countOtherTypesBeyondThreshold = (army: Card[]): number =>
  Math.max(countOtherTypes(army) - OTHER_TYPE_THRESHOLD, 0);

const scoreTypes = (army: Card[]): number => {
  const otherTypesBeyondThreshold = countOtherTypesBeyondThreshold(army);
  if (otherTypesBeyondThreshold === 0)
    return POINT_FOR_THREE_OTHER_TYPES_OR_FEWER;
  return POINTS_PER_OTHER_TYPE_BEYOND_THRESHOLD * otherTypesBeyondThreshold;
};

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return SCORE_WITHOUT_SPHINX;
  return SPHINX_POINT + scoreTypes(army);
};

