export type Card = {
  monster: string;
  rank?: number;
};

const SCORE_WITHOUT_SPHINX = 0;
const POINT_FOR_THE_SPHINX_ITSELF = 1;
const POINT_FOR_THREE_OTHER_TYPES_OR_FEWER = 1;
const OTHER_TYPE_THRESHOLD = 3;
const POINTS_PER_OTHER_TYPE_BEYOND_THRESHOLD = 2;
/** The Sphinx scores the *company* it keeps, so its own type is not counted. */
const SPHINX_OWN_TYPE = 1;

const countSphinxes = (army: Card[]): number =>
  army.filter((card) => card.monster === "sphinx").length;

const countTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

const countOtherTypes = (army: Card[]): number =>
  countTypes(army) - SPHINX_OWN_TYPE;

const countOtherTypesBeyondThreshold = (army: Card[]): number =>
  Math.max(countOtherTypes(army) - OTHER_TYPE_THRESHOLD, 0);

/** The bonus one Sphinx earns from the variety of monsters keeping it company. */
const scoreCompanyOfOneSphinx = (army: Card[]): number => {
  const otherTypesBeyondThreshold = countOtherTypesBeyondThreshold(army);
  if (otherTypesBeyondThreshold === 0)
    return POINT_FOR_THREE_OTHER_TYPES_OR_FEWER;
  return POINTS_PER_OTHER_TYPE_BEYOND_THRESHOLD * otherTypesBeyondThreshold;
};

export const scoreArmy = (army: Card[]): number => {
  const sphinxes = countSphinxes(army);
  if (sphinxes === 0) return SCORE_WITHOUT_SPHINX;
  return sphinxes * (POINT_FOR_THE_SPHINX_ITSELF + scoreCompanyOfOneSphinx(army));
};

